 void updateDevices(){
  if(deviceRows==null||service==null)return;
  Ble ble=service.ble;String active=ble.g==null?"":ble.g.getDevice().getAddress();boolean valid=service.snapshot().optBoolean("bmsValid");
  stateBadge(deviceBadge,valid?"已连接":!active.isEmpty()?"等待数据":"未连接",valid);deviceInfo.setText("BLE GATT · "+(active.isEmpty()?"未连接":active)+(valid?" · 电池数据有效":""));
  ArrayList<BluetoothDevice> now=new ArrayList<>(ble.devices.values());if(ble.g!=null&&!ble.devices.containsKey(active))now.add(0,ble.g.getDevice());
  ArrayList<String> labels=new ArrayList<>();for(BluetoothDevice d:now){String addr=d.getAddress(),name=ble.name(d);Integer rssi=ble.rssi.get(addr);labels.add(name+"\n"+addr+(rssi==null?"":" · "+rssi+" dBm")+"|"+(addr.equals(active)?valid?"connected":"pending":"other"));}
  deviceCount.setText((ble.scanning?"扫描中":"扫描结果")+" · "+ble.devices.size()+" 台设备");
  if(labels.equals(renderedDevices))return;renderedDevices=labels;deviceRows.removeAllViews();
  for(int i=0;i<now.size();i++){final BluetoothDevice d=now.get(i);String addr=d.getAddress(),name=ble.name(d);boolean selected=addr.equals(active),supported=ble.supports(d);Integer rssi=ble.rssi.get(addr);
   LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(0,dp(10),0,dp(10));LinearLayout left=vertical();left.addView(label(name,16,FG,true));gap(left,4);left.addView(label(addr+(rssi==null?"":" · "+rssi+" dBm"),11,MUT,false));row.addView(left,new LinearLayout.LayoutParams(0,-2,1));
   String title=selected?(valid?"已连接":"等待数据"):supported?"连接":"不支持";TextView connect=action(title,selected&&valid?BG:supported?AQUA:MUT,selected&&valid?AQUA:CARD,supported?AQUA:BORDER,()->{if(service!=null&&supported&&!selected)service.ble.connect(d,Protocol.Kind.BAOLIAN);});connect.setEnabled(supported&&!selected);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(dp(76),dp(40));bp.leftMargin=dp(8);row.addView(connect,bp);deviceRows.addView(row);View divider=new View(this);divider.setBackgroundColor(BORDER);deviceRows.addView(divider,new LinearLayout.LayoutParams(-1,dp(1)));
  }
 }
