 void updateCells(JSONObject j){if(cellDelta==null)return;cellDelta.setText("压差 "+f(j,"delta",3)+" V");JSONArray a=j.optJSONArray("cells");double min=Double.POSITIVE_INFINITY,max=Double.NEGATIVE_INFINITY;for(int i=0;i<20;i++){double n=a==null?Double.NaN:a.optDouble(i,Double.NaN);if(Double.isFinite(n)){min=Math.min(min,n);max=Math.max(max,n);}}for(int i=0;i<20;i++){double n=a==null?Double.NaN:a.optDouble(i,Double.NaN);cellValues[i].setText(Double.isFinite(n)?String.format(Locale.US,"%.3f",n):"—");cellValues[i].setTextColor(Double.isFinite(n)&&max>min?(n==max?AMBER:n==min?AQUA:FG):FG);}}
